async def prepare_call_context(call_data: dict):
    """Pre-call: turn raw lead + property data into speakable, pre-computed facts.

    Reads call metadata supplied at call time (lead_* and property fields, units_json as a
    JSON string or list) and ADDS derived keys used by the prompt:
      units_spoken, lead_budget_spoken, budget_fit, budget_fit_note, enquiry_recency,
      time_greeting, offer_line, scarcity_line, opening_language, missing_facts.
    The LLM never does arithmetic: every comparison and amount is computed here.
    Never raises: on any error the prompt falls back to its missing-data rules.
    """
    metadata = call_data.setdefault("metadata", {})

    def s(key):
        v = metadata.get(key)
        return "" if v is None else str(v).strip()

    def inr(amount):
        a = float(amount)
        if a >= 10000000:
            v = round(a / 10000000, 2)
            return "₹" + ("%g" % v) + " crore"
        v = round(a / 100000, 1)
        return "₹" + ("%g" % v) + " lakh"

    def gap(amount):
        return inr(amount).replace("₹", "about ₹", 1)

    try:
        # ---------- units ----------
        raw_units = metadata.get("units_json")
        units = []
        if isinstance(raw_units, list):
            units = raw_units
        elif raw_units:
            try:
                units = json.loads(str(raw_units))
            except Exception:
                units = []
        clean = []
        for u in units:
            try:
                clean.append({
                    "config": str(u["config"]).strip(),
                    "area": int(float(u.get("carpet_sqft") or 0)),
                    "area_type": str(u.get("area_type") or "carpet").strip(),
                    "lo": float(u["price_min_inr"]),
                    "hi": float(u["price_max_inr"]),
                })
            except Exception:
                continue
        clean.sort(key=lambda x: x["lo"])
        if clean:
            parts = []
            for u in clean:
                area = ("%s sq ft %s" % (format(u["area"], ","), u["area_type"])) if u["area"] else ""
                price = inr(u["lo"]) if u["lo"] == u["hi"] else "%s to %s" % (inr(u["lo"]), inr(u["hi"]))
                parts.append("%s%s: %s" % (u["config"], (" (" + area + ")") if area else "", price))
            metadata["units_spoken"] = "; ".join(parts)
        else:
            metadata["units_spoken"] = "NOT AVAILABLE"

        # ---------- budget fit ----------
        budget = None
        b_raw = s("lead_budget_inr").replace(",", "")
        if b_raw:
            try:
                budget = float(b_raw)
                if budget <= 0:
                    budget = None
            except Exception:
                budget = None
        metadata["lead_budget_spoken"] = inr(budget) if budget else "not stated"

        if budget is None or not clean:
            metadata["budget_fit"] = "unknown"
            metadata["budget_fit_note"] = ("The lead's budget is not known. Ask for it; do not judge fit yourself."
                                           if clean else "Unit prices are not available. Do not discuss prices.")
        else:
            notes = []
            any_fit = False
            any_stretch = False
            for u in clean:
                if u["hi"] <= budget:
                    any_fit = True
                    notes.append("%s fits fully within the budget" % u["config"])
                elif u["lo"] <= budget:
                    any_fit = True
                    notes.append("%s fits at the lower end of its range (starts at %s; the top of the range is %s above budget)"
                                 % (u["config"], inr(u["lo"]), gap(u["hi"] - budget)))
                elif u["lo"] <= budget * 1.10:
                    any_stretch = True
                    notes.append("%s starts %s above budget, a stretch of under 10 percent" % (u["config"], gap(u["lo"] - budget)))
                else:
                    notes.append("%s starts %s above budget" % (u["config"], gap(u["lo"] - budget)))
            metadata["budget_fit"] = "fits" if any_fit else ("stretch" if any_stretch else "below_range")
            if not any_fit and not any_stretch:
                notes.append("no configuration here fits this budget; be honest and do not push")
            metadata["budget_fit_note"] = "Budget %s. " % inr(budget) + "; ".join(notes) + "."

        # ---------- time ----------
        tz = pytz.timezone("Asia/Kolkata")
        now = datetime.now(tz)
        h = now.hour
        metadata["time_greeting"] = "good morning" if h < 12 else ("good afternoon" if h < 17 else "good evening")
        enq = s("enquiry_at")
        recency = "recently"
        if enq and enq.lower() != "auto":
            try:
                t = datetime.fromisoformat(enq.replace("Z", "+00:00"))
                if t.tzinfo is None:
                    t = tz.localize(t)
                mins = int((now - t).total_seconds() // 60)
                if mins < 2:
                    recency = "just a minute ago"
                elif mins < 60:
                    recency = "about %d minutes ago" % mins
                elif mins < 180:
                    recency = "a little while ago today"
                else:
                    recency = "earlier"
            except Exception:
                recency = "recently"
        elif enq.lower() == "auto":
            recency = "a few minutes ago"
        metadata["enquiry_recency"] = recency

        # ---------- offer & scarcity: only real facts, else an explicit NONE ----------
        offer = s("current_offer")
        valid = s("offer_valid_till")
        if offer and valid:
            try:
                if datetime.strptime(valid, "%Y-%m-%d").date() < now.date():
                    offer = ""
            except Exception:
                pass
        metadata["offer_line"] = offer if offer else "NONE"
        inv = s("inventory_fact")
        metadata["scarcity_line"] = inv if inv else "NONE"

        # ---------- language ----------
        lang = s("lead_language").lower()
        metadata["opening_language"] = {"english": "English", "hindi": "Hindi", "hinglish": "Hinglish"}.get(lang, "Hinglish")

        # ---------- missing facts the agent must not improvise ----------
        required = ["property_name", "city", "locality", "possession", "rera_id", "price_basis",
                    "amenities", "location_highlights", "payment_plan", "loan_partners", "site_address"]
        missing = [k for k in required if not s(k)]
        for k in missing:
            metadata[k] = "NOT AVAILABLE"
        metadata["missing_facts"] = ", ".join(missing) if missing else "none"
        for k in ["lead_name", "enquiry_source", "lead_config_pref", "lead_note", "sales_manager_name",
                  "construction_status", "property_type"]:
            if not s(k):
                metadata[k] = "NOT AVAILABLE"
    except Exception as error:
        logger.warning("prepare_call_context failed: %s", error)

    call_data["metadata"] = metadata

async def check_visit_slots(ctx: RunContext, property_id: str, preferred_day: str) -> dict:
    """Fetch open site-visit slots for this property from the Bluepoint Sales Desk.

    Args:
        ctx: run context
        property_id: str — the property id from the call data, e.g. BP-PUN-SKY
        preferred_day: str — "today", "tomorrow", a weekday name ("saturday"), "weekend",
            "weekday", or "" for the earliest slots

    Returns:
        dict: {status: "success", slots: [{slot_id, label}], note} or
              {status: "error", message}
    """
    pid = (property_id or "").strip().upper()
    if not pid:
        return {"status": "error", "message": "property_id is required"}
    day = (preferred_day or "").strip().lower()
    allowed = {"", "any", "today", "tomorrow", "weekend", "weekday", "monday", "tuesday", "wednesday",
               "thursday", "friday", "saturday", "sunday"}
    if day not in allowed:
        day = ""
    try:
        async with httpx.AsyncClient(timeout=8.0) as client:
            resp = await client.post(
                "https://xtvqhihnoxuyfwpylrtj.supabase.co/rest/v1/rpc/get_visit_slots",
                headers={"apikey": x_secrets["BLUEPOINT_DESK_KEY"], "Content-Type": "application/json"},
                json={"p_property_id": pid, "p_preferred_day": day, "p_limit": 3},
            )
    except httpx.RequestError as e:
        return {"status": "error", "message": "Scheduling system unreachable: %s" % e}
    if resp.status_code >= 300:
        return {"status": "error", "message": "Scheduling system error %s" % resp.status_code}
    try:
        data = resp.json()
    except Exception:
        return {"status": "error", "message": "Scheduling system returned an unreadable response"}
    if data.get("status") != "success":
        return {"status": "error", "message": data.get("message", "unknown error")}
    return {"status": "success", "slots": data.get("slots", []), "note": data.get("note", "")}

async def book_site_visit(ctx: RunContext, property_id: str, slot_id: int, visitor_name: str, visitors: int, notes: str) -> dict:
    """Book one site-visit slot in the Bluepoint Sales Desk and return a booking reference.

    Args:
        ctx: run context
        property_id: str — the property id from the call data
        slot_id: int — a slot_id returned by check_visit_slots in THIS call and chosen by the lead
        visitor_name: str — the lead's name as they want it on the booking
        visitors: int — number of people coming (1-10)
        notes: str — short notes for the sales manager (preferences, questions), or ""

    Returns:
        dict: {status: "success", booking_ref, slot_label, visitors} or
              {status: "slot_full" | "error", message}
    """
    pid = (property_id or "").strip().upper()
    name = (visitor_name or "").strip()
    if not pid or not slot_id or int(slot_id) <= 0:
        return {"status": "error", "message": "property_id and a slot_id from check_visit_slots are required"}
    if not name or name.upper() == "NOT AVAILABLE":
        return {"status": "error", "message": "Ask the lead for the name to put on the booking first"}
    try:
        count = int(visitors) if visitors else 1
    except Exception:
        count = 1
    try:
        async with httpx.AsyncClient(timeout=8.0) as client:
            resp = await client.post(
                "https://xtvqhihnoxuyfwpylrtj.supabase.co/rest/v1/rpc/book_site_visit",
                headers={"apikey": x_secrets["BLUEPOINT_DESK_KEY"], "Content-Type": "application/json"},
                json={"p_property_id": pid, "p_slot_id": int(slot_id), "p_lead_name": name,
                      "p_visitors": max(1, min(count, 10)), "p_notes": (notes or "")[:500]},
            )
    except httpx.RequestError as e:
        return {"status": "error", "message": "Booking system unreachable: %s" % e}
    if resp.status_code >= 300:
        return {"status": "error", "message": "Booking system error %s" % resp.status_code}
    try:
        data = resp.json()
    except Exception:
        return {"status": "error", "message": "Booking system returned an unreadable response"}
    if data.get("status") == "success":
        ref = str(data.get("booking_ref") or "")
        # Spell it out for TTS so the reference is never garbled ("BV-7Q2K" -> "B V 7 Q 2 K").
        spoken = " ".join(ch for ch in ref.upper() if ch.isalnum())
        return {"status": "success", "booking_ref": ref, "booking_ref_spoken": spoken,
                "slot_label": data.get("slot_label"), "visitors": data.get("visitors")}
    return {"status": data.get("status", "error"), "message": data.get("message", "booking failed")}

async function handoff_to_closer(context) {
  const pc = context.post_call || {};
  const md = context.call_metadata || {};
  const get = (k) => (pc[k] !== undefined && pc[k] !== null ? String(pc[k]).trim() : "");
  const outcome = get("outcome") || "no_conversation";
  // Normalise the extracted booking reference ("BV8CB7", "bv 8cb7" -> "BV-8CB7") so it matches the Sales Desk record.
  let bookingRef = get("site_visit_booking_ref").toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (/^BV[A-Z0-9]{4}$/.test(bookingRef)) bookingRef = "BV-" + bookingRef.slice(2);
  if (bookingRef) pc.site_visit_booking_ref = bookingRef;
  const optedOut = pc.opted_out === true || String(pc.opted_out).toLowerCase() === "true" || outcome === "opted_out";

  // Deterministic lead score (0-100): the same answers always give the same score.
  const outcomePts = { site_visit_booked: 40, human_callback_requested: 30, callback_scheduled: 20, nurture_follow_up: 10 };
  const fitPts = { fits: 20, stretch: 12, unknown: 5, below_range: 0 };
  const timelinePts = { "0_3_months": 20, "3_6_months": 14, "6_12_months": 7, over_12_months: 2, unknown: 3 };
  const purposePts = { self_use: 10, both: 10, investment: 8, unknown: 3 };
  const loanPts = { not_needed: 10, needed: 7, undecided: 4, unknown: 3 };
  let score = (outcomePts[outcome] || 0) + (fitPts[get("budget_fit")] ?? 3) + (timelinePts[get("purchase_timeline")] ?? 3)
            + (purposePts[get("buyer_purpose")] ?? 3) + (loanPts[get("home_loan")] ?? 3);
  if (["not_interested", "wrong_person", "no_conversation"].includes(outcome) || optedOut) score = 0;
  score = Math.max(0, Math.min(100, score));

  let temperature = score >= 70 ? "hot" : score >= 45 ? "warm" : "cold";
  if (optedOut) temperature = "do_not_call";
  else if (outcome === "wrong_person") temperature = "disqualified";
  let priority = optedOut ? "none" : (temperature === "hot" || outcome === "site_visit_booked") ? "P1" : temperature === "warm" ? "P2" : "P3";

  const dispositions = {
    site_visit_booked: "Site visit booked",
    human_callback_requested: "Wants a call from the sales manager",
    callback_scheduled: "Busy, asked for a callback",
    nurture_follow_up: "Interested later, nurture",
    not_interested: "Not interested",
    opted_out: "Opted out, do not call",
    wrong_person: "Wrong person",
    no_conversation: "No conversation"
  };

  pc.lead_score = score;
  pc.lead_temperature = temperature;
  pc.lead_priority = priority;
  context.disposition_reason = dispositions[outcome] || outcome;
  context.conversion_status = outcome === "site_visit_booked" && bookingRef !== "";

  const payload = {
    call_sid: context.callSid ?? null,
    property_id: md.property_id ?? null,
    lead_name: md.lead_name ?? null,
    lead_phone: context.user_phone_number ?? null,
    outcome,
    opted_out: optedOut,
    lead_temperature: temperature,
    lead_score: score,
    priority,
    booking_ref: bookingRef,
    site_visit_slot: get("site_visit_slot"),
    callback_time: get("callback_time"),
    budget_confirmed: get("budget_confirmed"),
    budget_fit: get("budget_fit"),
    config_interest: get("config_interest"),
    buyer_purpose: get("buyer_purpose"),
    purchase_timeline: get("purchase_timeline"),
    home_loan: get("home_loan"),
    objections: get("objections_raised"),
    unanswered_questions: get("unanswered_questions"),
    competitors_mentioned: get("competitors_mentioned"),
    language_used: get("language_used"),
    closer_summary: get("closer_summary"),
    next_best_action: get("next_best_action"),
    call_duration: context.call_duration ?? null,
    recording_url: context.recordingUrl ?? null
  };

  const functionLog = {
    name: "handoff_to_closer",
    parameters: { call_sid: payload.call_sid, outcome, lead_score: score, priority },
    success: false,
    response: null,
    timestamp: new Date().toISOString()
  };
  try {
    const res = await axios({
      method: "POST",
      url: "https://xtvqhihnoxuyfwpylrtj.supabase.co/rest/v1/rpc/record_handoff",
      headers: { apikey: x_secrets["BLUEPOINT_DESK_KEY"], "Content-Type": "application/json" },
      data: { p: payload },
      timeout: 10000
    });
    functionLog.success = res.status >= 200 && res.status < 300;
    functionLog.response = res.data;
  } catch (error) {
    functionLog.response = error.message;
  } finally {
    context.functions_called.push(functionLog);
  }
}
